const names={submitted:'ส่งเคสแล้ว',received:'ร้านรับเรื่อง',checking:'กำลังตรวจเช็ค',awaiting_approval:'รออนุมัติราคา',repairing:'กำลังซ่อม',ready:'พร้อมรับเครื่อง',closed:'ปิดเคส',cancelled:'ยกเลิก'};
let dataset=null;
function el(tag,text='',cls=''){const e=document.createElement(tag);e.textContent=text;e.className=cls;return e;}
async function api(path,method='GET',body){const r=await fetch('/api'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let d;try{d=await r.json();}catch{throw new Error('หน้านี้ใช้ผ่าน backend local เท่านั้น');}if(!r.ok)throw new Error(typeof d.detail==='string'?d.detail:'ตรวจข้อมูลที่กรอกอีกครั้ง');return d;}
const filter=document.querySelector('#admin-filter');filter.append(el('option','ทุกสถานะ'));filter.firstChild.value='all';for(const [k,v] of Object.entries(names)){const o=el('option',v);o.value=k;filter.append(o);}
function render(){const stats=document.querySelector('#admin-stats');stats.replaceChildren();for(const [k,v] of Object.entries(dataset.counts)){const box=el('div');box.append(el('strong',String(v)),el('span',names[k]));stats.append(box);}const list=document.querySelector('#admin-list');list.replaceChildren();const rows=dataset.cases.filter(c=>filter.value==='all'||c.status===filter.value);if(!rows.length)list.append(el('p','ไม่มีเคสในสถานะนี้','member-hint'));
 for(const c of rows){const row=el('article','','member-row');row.append(el('strong',c.reference+' · '+c.model+' · '+c.member_name),el('span',names[c.status],'status-badge'),el('p',c.issue));const detail=el('button','ประวัติสถานะและแชทที่แนบ','member-action');detail.onclick=async()=>{try{const d=await api('/admin/cases/'+c.id),box=el('div','','admin-detail');for(const e of d.events)box.append(el('p',names[e.status]+' · '+e.note+' · '+new Date(e.created*1000).toLocaleString('th-TH')));if(d.messages.length)box.append(el('strong','บทสนทนาที่สมาชิกแนบ'));for(const m of d.messages)box.append(el('p',(m.role==='user'?'สมาชิก: ':'ผู้ช่วย: ')+m.content));row.querySelector('.admin-detail')?.remove();row.append(box);}catch(e){document.querySelector('#admin-error').textContent=e.message;}};row.append(detail);
   if(c.quote)row.append(el('p','ใบเสนอ #'+c.quote.id+' · '+Number(c.quote.amount).toLocaleString('th-TH')+' บาท · '+({pending:'รอลูกค้าอนุมัติ',approved:'ลูกค้าอนุมัติแล้ว',rejected:'ลูกค้าปฏิเสธ',superseded:'ถูกแทนด้วยใบเสนอใหม่'}[c.quote.status])));
   const next=c.allowed_transitions||dataset.transitions[c.status];if(next.length){const form=el('form','','admin-case-form'),sl=el('label','สถานะถัดไป'),sel=el('select');for(const v of next){const o=el('option',v==='awaiting_approval'&&c.status==='awaiting_approval'?'ส่งราคาใหม่ให้อนุมัติ':names[v]);o.value=v;sel.append(o);}sl.append(sel);const nl=el('label','หมายเหตุ','note-field'),note=el('input');note.required=true;note.minLength=3;note.maxLength=1000;nl.append(note);const pl=el('label','ราคาเสนอ (สาธิต)'),price=el('input');price.type='number';price.min='0';price.max='1000000';price.step='.01';price.value=c.quoted_price??'';pl.append(price);const save=el('button','อัปเดตสถานะ');save.type='submit';form.append(sl,nl,pl,save);form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{await api('/admin/cases/'+c.id,'PATCH',{status:sel.value,note:note.value,quoted_price:price.value===''?null:Number(price.value)});await load();}catch(err){document.querySelector('#admin-error').textContent=err.message;save.disabled=false;}};row.append(form);}list.append(row);
 }}
async function load(){document.querySelector('#admin-error').textContent='';try{dataset=await api('/admin/cases');render();}catch(e){document.querySelector('#admin-error').textContent=e.message;document.querySelector('#admin-list').replaceChildren();}}
filter.onchange=()=>dataset&&render();document.querySelector('#admin-refresh').onclick=load;load();
